def main():
    parser = argparse.ArgumentParser(description='고양모터스 TPS 포트맵 단일 파일 웹앱')
    parser.add_argument('--port', type=int, default=8080, help='서버 포트 (기본 8080)')
    parser.add_argument('--lan', action='store_true', help='같은 네트워크의 휴대폰 접속 허용')
    parser.add_argument('--no-browser', action='store_true', help='브라우저 자동 열기 생략')
    args = parser.parse_args()
    if not 1 <= args.port <= 65535:
        parser.error('포트 번호는 1~65535 범위여야 합니다.')
    try:
        server = Server(('0.0.0.0' if args.lan else '127.0.0.1', args.port), Handler)
    except OSError as exc:
        print(f'서버 시작 실패: {exc}\n다른 포트를 지정하세요: --port 8081')
        return 1
    url = f'http://localhost:{args.port}/'
    print(f'고양모터스 TPS 포트맵 실행 중\nPC 접속: {url}\n종료: Ctrl+C')
    if args.lan:
        print('휴대폰: PC와 같은 Wi-Fi에서 http://PC의IPv4주소:%d/ 접속' % args.port)
        print('PC IPv4 주소는 Windows ipconfig에서 확인할 수 있습니다.')
        print('휴대폰 접속 중에는 이 프로그램과 PC를 켜두세요. 필요 시 개인 네트워크 방화벽에서 Python을 허용하세요.')
        try:
            addresses = sorted({entry[4][0] for entry in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET)})
            for ip in addresses:
                if not ip.startswith('127.'):
                    print(f'접속 주소 후보: http://{ip}:{args.port}/')
        except OSError:
            pass
    if not args.no_browser:
        webbrowser.open(url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print('\n포트맵을 종료합니다.')
    finally:
        server.server_close()
    return 0

