#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""고양모터스 TPS 포트맵 — 단일 파일 웹앱 (Python 3.9 이상)

실행: python TPS_PortMap_Single.py
같은 Wi-Fi 휴대폰 접속: python TPS_PortMap_Single.py --lan
포트 변경: python TPS_PortMap_Single.py --port 8081
종료: 터미널에서 Ctrl+C

추가 패키지, model.py, 엑셀 파일 없이 실행됩니다.
HTML/CSS/JavaScript/포트맵/아이콘이 이 파일 안에 포함되어 있습니다.
웹 UI는 브라우저가 실행하고 Python은 내장된 자료만 제공합니다.
--lan 사용 시 같은 네트워크 사용자가 로그인 없이 포트맵을 볼 수 있습니다.
휴대폰의 HTTP LAN 접속에서는 오프라인/PWA 설치 기능이 제한될 수 있습니다.
정식 HTTPS 웹앱: https://goyang-tps-portmap.tastyyak1.chatgpt.site
"""
import argparse
import base64
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import socket
from urllib.parse import urlsplit, unquote
import webbrowser

# 내장 웹앱 소스: 외부 파일을 읽거나 생성하지 않습니다.
ASSETS = {}

# ---- app.js ----
ASSETS['/app.js'] = 'import {esc, allDevices, searchDevices, modeClass, filterPorts, physicalBanks, portFaceContent, vlanGroups, roomCounts, vlanTextLayout, vlanIdentity, applyPortNames, portStatusText, autoLabel} from './core.js';

const root = document.querySelector('#app');
const descriptionLegend='<span class="description-legend"><span class="legend-star" aria-hidden="true">★</span> Description 있음</span>';
let data, currentDevice, filterMode='all', filterQuery='', copyText='', installPrompt, selectedPort, groupVlan=false;
const $ = id => document.getElementById(id);
const routeLink = (key,value) => '#'+key+'='+encodeURIComponent(value);
const crumb = room => `<nav class="breadcrumbs" aria-label="현재 위치"><a href="#">모든 TPS실</a>${room?`<span>/</span><a href="${routeLink('room',room)}">${esc(room)}</a>`:''}${currentDevice?'<span>/</span><span>장비 포트맵</span>':''}</nav>`;

function toast(text) { $('toast').textContent=text; $('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3000); }
function title(text) { document.title=text+' · 고양모터스 포트맵'; }
function deviceCard(d) {
  const note=d.isRemoved?'제거해야 되는 장비':d.isNew?'신규 장비':'대개체 장비';
  return `<a class="device-card ${d.isRemoved?'removed-device':d.isNew?'new-device':''}" href="${routeLink('device',d.ip)}"><span class="pill ${d.isRemoved?'warning':d.isNew?'new':''}">${esc(note)}</span><h2>${esc(d.name)}</h2><div class="device-ip">${esc(d.ip)}</div><p class="room-meta">${d.isNew&&!d.ports.length?'포트 정보 등록 예정':`${d.ports.length}개 포트`} · ${esc(d.room)}</p><span class="arrow" aria-hidden="true">↗</span></a>`;
}
function home() {
  title('TPS실 선택');
  const ds=allDevices(data),counts=roomCounts(ds);
  root.innerHTML=`<section class="hero"><div><div class="eyebrow">Goyang motors / field reference</div><h1>어느 TPS실에서<br>작업하시나요?</h1><p class="lead">TPS실 선택 후, 장비를 선택하면 모든 포트의 설정을 볼 수 있습니다.</p></div><div class="home-statistics"><p class="developer-credit">앱 개발 : 정재호 선임</p><div class="stat-strip"><div class="stat"><b>${counts.replacement+counts.removed}</b><span>기존 장비</span></div><div class="stat"><b>${counts.replacement}</b><span>대개체 장비</span></div><div class="stat"><b>${counts.removed}</b><span>제거 장비</span></div><div class="stat"><b>${counts.added}</b><span>신규 장비</span></div><div class="stat"><b>${counts.replacement+counts.added}</b><span>작업 후 장비</span></div></div></div></section><div class="section-label"><span>TPS실 선택</span></div><section class="room-grid">${data.rooms.map((r,i)=>`<a class="room-card" href="${routeLink('room',r.name)}"><span class="room-number">TPS ${String(i+1).padStart(2,'0')}</span><h2>${esc(r.name)}</h2><p class="room-meta">대개체 ${roomCounts(r.devices).replacement}대 / 신규 ${roomCounts(r.devices).added}대 / 제거 ${roomCounts(r.devices).removed}대</p></a>`).join('')}</section>`;
  requestAnimationFrame(fitRoomCounts);
}
function roomView(name) {
  const r=data.rooms.find(r=>r.name===name);
  if(!r) return notFound();
  title(name);
  const counts=roomCounts(r.devices);
  root.innerHTML=`<div class="room-navigation"><a class="overview-home" href="#" aria-label="홈 · 모든 TPS실">⌂ 홈</a>${crumb(name)}</div><section class="hero"><div><div class="eyebrow">TPS ROOM</div><h1>${esc(name)}</h1><p class="lead">대개체 ${counts.replacement}대 / 신규 ${counts.added}대 / 제거 ${counts.removed}대 · 총 ${r.devices.length}대</p></div></section><section class="device-grid">${r.devices.map(deviceCard).join('')}</section>`;
}
function searchView(q) {
  const ds=searchDevices(data,q);title('장비 검색');
  root.innerHTML=`${crumb()}<section class="hero"><div><div class="eyebrow">DEVICE SEARCH</div><h1>장비 검색</h1><p class="lead">“${esc(q)}” · ${ds.length}개 결과</p></div></section>${ds.length?`<section class="device-grid">${ds.map(deviceCard).join('')}</section>`:'<div class="empty-state"><h2>일치하는 장비가 없습니다</h2><p>IP, 교체 전·후 이름 또는 TPS실 이름을 확인하세요.</p><a class="primary" href="#">TPS실 목록 보기</a></div>'}`;
}
function notFound() { title('장비 찾기');root.innerHTML=`${crumb()}<div class="empty-state"><h2>해당 장비 또는 TPS실을 찾을 수 없습니다</h2><p>최신 포트맵에서 다시 선택해주세요.</p><a class="primary" href="#">처음으로</a></div>`; }
function physicalPanel(ports){
  return physicalBanks(ports).map(bank=>`<section class="physical-bank ${bank.kind}" style="--bank-cols:${bank.columns};flex:${bank.columns}"><div class="bank-caption">${esc(bank.label)}</div><div class="bank-ports">${bank.ports.map(p=>`<button class="overview-port ${modeClass(p)}" style="grid-column:${p.panelColumn};grid-row:${p.panelRow}" data-overview-port="${esc(p.name)}" aria-pressed="false" aria-label="${esc(p.name+' '+(p.mode||'')+' VLAN '+p.vlan+(p.description?' Description 있음':''))}" title="${esc(p.name+' | '+(p.mode||'')+' | '+p.vlan)}">${portFaceContent(p)}</button>`).join('')}</div></section>`).join('');
}
function statusStatistics(d){
  const c=d.portStatusCounts;
  return c?`<div class="port-status-stats" aria-label="포트상태 통계"><div><span class="count-up">UP 포트 : <b>${c.UP}</b>개</span><span class="stat-separator">/</span><span class="count-down">Down 포트(Shutdown포트 미포함) : <b>${c.DOWN}</b>개</span><span class="stat-separator">/</span><span class="count-shutdown">Shutdown 포트 : <b>${c.ADM}</b>개</span></div><small>제공된 상태 자료 기준</small></div>`:'<div class="port-status-stats"><small>포트상태 자료 없음</small></div>';
}
function overviewDevice(ip){
  const d=allDevices(data).find(d=>d.ip===ip);
  if(!d)return notFound();
  currentDevice=d;selectedPort=d.ports[0]?.name;filterMode='all';filterQuery='';groupVlan=false;title(d.name);
  document.body.classList.add('device-overview');
  refreshViewport();
  root.innerHTML=`<div class="overview-heading"><a class="overview-home" href="#" aria-label="홈 · 모든 TPS실">⌂ 홈</a><a class="back-room overview-home" href="${routeLink('room',d.room)}" aria-label="${esc(d.room)} 장비 목록">‹ <span>뒤로</span></a><div class="overview-title"><h1>${esc(d.name)}</h1><div class="overview-ip">${esc(d.ip)}</div><div class="device-category ${d.isRemoved?'removed':''}">${d.isRemoved?'제거해야 되는 장비':d.isNew?'신규 장비':'대개체 장비'}</div></div>${statusStatistics(d)}</div>${d.isNew&&!d.ports.length?'<div class="empty-state"><h2>신규 장비 · 포트 정보 등록 예정</h2><p>포트 전면도와 설정은 정보를 받은 뒤 추가됩니다.</p></div>':`<div class="overview-controls"><div class="tabs" role="group" aria-label="포트 필터">${[['all','전체'],['access','Access'],['trunk','Trunk'],['description','Description'],['up','UP인 포트'],['down','Down된 포트'],['shutdown','Shutdown 포트']].map(([k,t])=>`<button data-mode="${k}" class="${k==='all'?'active':''}" aria-pressed="${k==='all'}">${t}</button>`).join('')}</div><button id="vlan-group-toggle" class="quiet" aria-pressed="false">동일 VLAN 포트 확인</button><input id="overview-search" type="search" aria-label="포트 VLAN Description 강조 검색" placeholder="번호 · VLAN · 설명"></div><div class="overview-caption"><span id="overview-count">${d.ports.length}개 포트</span><span id="color-key"><i class="dot-access"></i>Access <i class="dot-trunk"></i>Trunk / (voice) 보이스 브이랜 / (native) Native 브이랜 / ${descriptionLegend}</span></div><section class="single-switch ${d.ports.length<=28?'compact-chassis':''}" aria-label="전체 포트 한 화면 보기"><div class="switch-rail"><span>PORT PANEL</span><span>${d.status==='설정 미수령'?'설정 미수령':'상단 홀수 / 하단 짝수 · 모델별 실제 배치는 다를 수 있음'}</span><span aria-hidden="true">⊕</span></div><div id="overview-grid" class="overview-grid">${physicalPanel(d.ports)}</div></section><section id="selected-summary" class="selected-summary" aria-label="선택한 포트 전체 정보" aria-live="polite"></section>`}`;
  if(d.isNew&&!d.ports.length)return;
  document.querySelectorAll('[data-overview-port]').forEach(b=>b.onclick=()=>selectOverviewPort(b.dataset.overviewPort));
  document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{
    clearPortSelection();filterMode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});highlightOverview();
  });
  $('overview-search').oninput=e=>{clearPortSelection();filterQuery=e.target.value;highlightOverview();};
  $('vlan-group-toggle').onclick=()=>{groupVlan=!groupVlan;applyVlanGroups();};
  selectOverviewPort(selectedPort);
  requestAnimationFrame(fitPortText);
}
function applyVlanGroups(){
  const groups=vlanGroups(currentDevice.ports),byPort=new Map();
  for(const g of groups)for(const name of g.names)byPort.set(name,g);
  const toggle=$('vlan-group-toggle');
  toggle.classList.toggle('active',groupVlan);toggle.setAttribute('aria-pressed',String(groupVlan));
  document.querySelectorAll('[data-overview-port]').forEach(b=>{
    const g=byPort.get(b.dataset.overviewPort);
    b.classList.toggle('vlan-grouped',groupVlan&&!!g);
    b.classList.toggle('vlan-ungrouped',groupVlan&&!g);
    b.style.setProperty('--vlan-group-color',g?.color||'#e2e8f0');
    b.querySelector('.vlan-group-badge')?.remove();
    if(groupVlan&&g)b.insertAdjacentHTML('beforeend',`<span class="vlan-group-badge">G${g.id}</span>`);
  });
  $('color-key').innerHTML=(groupVlan?`VLAN 번호·개수 기준 ${groups.length}그룹 · 역할 무관 · 공란 제외`:'Access Trunk / (voice) 보이스 브이랜 / (native) Native 브이랜')+' / '+descriptionLegend;
  if(selectedPort)selectOverviewPort(selectedPort);
  requestAnimationFrame(fitPortText);
}
function clearPortSelection(){
  selectedPort=null;copyText='';
  document.querySelectorAll('[data-overview-port]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});
  $('port-dialog').close();$('port-detail').innerHTML='';
  $('selected-summary').innerHTML='<div class="selection-hint">포트를 선택하면 VLAN과 Description 상세 정보를 확인할 수 있습니다.</div>';
}
function highlightOverview(){
  const matched=new Set(filterPorts(currentDevice.ports,filterMode,filterQuery).map(p=>p.name));
  document.querySelectorAll('[data-overview-port]').forEach(b=>b.classList.toggle('dimmed',!matched.has(b.dataset.overviewPort)));
  $('overview-count').textContent=`${matched.size} / ${currentDevice.ports.length}개 포트 강조${filterMode==='description'?' · Description 있음':''}`;
  if(!selectedPort)$('selected-summary').innerHTML=`<div class="selection-hint">${matched.size?'포트를 선택하면 상세 정보를 확인할 수 있습니다.':filterMode==='description'?'현재 조건에 맞는 Description이 있는 포트가 없습니다.':'현재 조건에 맞는 포트가 없습니다.'}</div>`;
}
function fitRoomCounts(){
  document.querySelectorAll('.room-card .room-meta').forEach(label=>{
    label.style.removeProperty('font-size');
    const font=parseFloat(getComputedStyle(label).fontSize);
    if(label.clientWidth>0 && label.scrollWidth>label.clientWidth){
      label.style.fontSize=(font*label.clientWidth/label.scrollWidth*.98)+'px';
    }
  });
}
function fitPortText(){
  if(window.visualViewport && Math.abs(window.visualViewport.scale-1)>.01)return;
  fitOverviewHeading();
  fitRoomCounts();
  document.querySelectorAll('.port-vlan-list').forEach(list=>{
    const n=Number(list.dataset.vlanCount),roles=Number(list.dataset.roleCount||0);
    const digits=Math.max(1,...[...list.querySelectorAll('.port-vlan-id')].map(el=>el.textContent.trim().length));
    // Both chassis sizes use the actual available row height; never grow the panel.
    const {gap,font}=vlanTextLayout(list.clientWidth,list.clientHeight,n,roles,digits);
    list.style.fontSize=font+'px';list.style.gap=gap+'px';
  });
}
function fitOverviewHeading(){
  const heading=document.querySelector('.overview-title h1');
  if(!heading)return;
  heading.style.removeProperty('font-size');
  const base=parseFloat(getComputedStyle(heading).fontSize);
  if(heading.scrollWidth>heading.clientWidth && heading.clientWidth>0){
    heading.style.fontSize=(base*heading.clientWidth/heading.scrollWidth*.98)+'px';
  }
}
function refreshViewport(){
  const viewport=window.visualViewport;
  // Pinch zoom only changes the visible window, never the chassis layout height.
  // Keep the last unzoomed geometry so the details cannot grow over the panel.
  if(viewport && Math.abs(viewport.scale-1)>.01)return;
  const height=viewport?viewport.height:window.innerHeight;
  document.documentElement.style.setProperty('--app-viewport-height',height+'px');
  requestAnimationFrame(()=>requestAnimationFrame(fitPortText));
}
window.addEventListener('resize',refreshViewport);
window.addEventListener('orientationchange',refreshViewport);
window.visualViewport?.addEventListener('resize',refreshViewport);
refreshViewport();
function selectOverviewPort(name){
  if(!name)return;selectedPort=name;
  const d=currentDevice,p=d.ports.find(p=>p.name===name);
  document.querySelectorAll('[data-overview-port]').forEach(b=>{b.classList.toggle('selected',b.dataset.overviewPort===name);b.setAttribute('aria-pressed',String(b.dataset.overviewPort===name));});
  $('selected-summary').innerHTML=`<div class="selected-ident"><strong>${esc(p.name)}</strong><span class="pill">${esc(p.mode||'')}${p.shutdown?' · shutdown':''}</span>${p.linkStatus?`<span class="selected-link-state">포트상태: ${esc(p.linkStatus==='ADM'?'Shutdown':p.linkStatus)}</span>`:''}</div><div class="selected-type"><b>타입</b><span>${esc(p.type||'—')}</span></div><div class="selected-settings"><div><b>VLAN</b><span>${esc(p.vlan||'')}</span></div><div class="selected-description"><div class="description-content"><b>Description</b><span>${esc(p.description||'')}</span></div><div class="description-action"><button id="selected-more" class="quiet">포트 상세 정보</button></div></div></div>`;
  if(groupVlan){
    const g=vlanGroups(d.ports).find(g=>g.names.includes(name));
    $('selected-summary').insertAdjacentHTML('beforeend',`<div class="group-detail">${g?`<b>G${g.id} · 동일 VLAN ${g.names.length}개 포트</b><span>VLAN ${esc(g.key)} (${g.key.split(',').length}개)</span>`:p.vlan.trim()?'VLAN 원문 확인 필요 · 그룹 제외':'VLAN 정보 없음 · 그룹 제외'}</div>`);
  }
  if(p.vlan.trim()&&vlanIdentity(p.vlan)===null)$('selected-summary').insertAdjacentHTML('beforeend','<div class="group-detail"><b>VLAN 원문 확인 필요</b><span>엑셀 원문을 보존했습니다. 동일 VLAN 그룹에서 제외됩니다.</span></div>');
  $('selected-more').onclick=()=>portDetail(name);
  requestAnimationFrame(fitPortText);
}

function portDetail(name) {
  const p=currentDevice.ports.find(p=>p.name===name),d=currentDevice;
  const fields=[['장비',`${d.name} (${d.ip})`],['포트',p.originalName],['MODE',p.mode||''],['VLAN 원문',p.vlan||''],['Description',p.description||''],['타입',p.type||''],['포트상태',portStatusText(p)]];
  if(p.vlan.trim()&&vlanIdentity(p.vlan)===null)fields.push(['확인사항','VLAN 원문 확인 필요 · 동일 VLAN 그룹 제외']);
  if(p.linkStatus)fields.push(['속도',autoLabel(p.linkSpeed)],['Duplex',autoLabel(p.linkDuplex)]);
  copyText=fields.map(([k,v])=>`${k}: ${v}`).join('\n');
  $('port-detail').innerHTML=`<h2>${esc(p.name)}</h2><dl class="detail-grid">${fields.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`;
  $('port-dialog').showModal();
}
function renderRoute() {
  if(!data)return;
  $('port-dialog').close();document.body.classList.remove('device-overview');currentDevice=null;
  const params=new URLSearchParams(location.hash.slice(1));
  if(params.has('device'))overviewDevice(params.get('device'));
  else if(params.has('room'))roomView(params.get('room'));
  else if(params.has('search'))searchView(params.get('search'));
  else home();
  window.scrollTo(0,0);root.focus({preventScroll:true});
}
$('search-form').addEventListener('submit',e=>{
  e.preventDefault();if(!data)return;
  const q=$('global-search').value.trim();if(!q){location.hash='';return;}
  const ds=searchDevices(data,q);
  const hash=ds.length===1?routeLink('device',ds[0].ip):routeLink('search',q);
  if(location.hash===hash)renderRoute();else location.hash=hash;
});
$('close-port').onclick=()=>$('port-dialog').close();
$('close-install').onclick=()=>$('install-dialog').close();
