export function correctedPortName(name, isNew, userPortCount, deviceName='') {
  const text=String(name??'');
  if(!isNew && userPortCount===24 && /^(Gi|XGE)1\/1\/[1-4](?=$|_)/i.test(text)) return text.replace(/^(?:Gi|XGE)1\/1\/([1-4])/i,(_,port)=>'XGE1/0/'+(24+Number(port)));
