  if(/^Gi1\/1\/[1-4](?=$|_)/i.test(text)) return text.replace(/^Gi/i,isNew?'Te':'XGE');
  const user=text.match(/^(?:Gi|G)(\d+\/0\/(\d+))(?=$|_)/i);
  if(!isNew && user && Number(user[2])>=1 && Number(user[2])<=userPortCount) return text.replace(/^(Gi|G)/i,'GE');
  return text;
