// Compare assigned VLAN IDs only; role labels and input order are not part of identity.
export function vlanIdentity(value) {
  const clean=String(value??'').replace(/\((?:voice|native|data)\)/gi,'').trim();
  if(!clean)return null;
  const ids=new Set();
  for(const token of clean.split(/[,;\s]+/).filter(Boolean)){
    const match=token.match(/^(\d+)(?:-(\d+))?$/);
    if(!match)return null;
    const a=Number(match[1]),b=Number(match[2]??match[1]);
    if(a<1||b>4094||b<a)return null;
    for(let id=a;id<=b;id++)ids.add(id);
  }
  return ids.size?[...ids].sort((a,b)=>a-b).join(','):null;
}
export function vlanGroups(ports){
  const buckets=new Map();
  for(const p of ports){const key=vlanIdentity(p.vlan);if(key===null)continue;
    if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(p.name);}
