  return [...buckets].sort(([a],[b])=>a.localeCompare(b,'en',{numeric:true})).map(([key,names],i)=>({
    key,names,id:i+1,color:palette[i]??`hsl(${(i*137.508)%360} 65% 80%)`
  }));
}

export function roomCounts(devices){
  const added=devices.filter(d=>d.isNew).length;
  const removed=devices.filter(d=>d.isRemoved).length;
  return {added,removed,replacement:devices.length-added-removed};
}
export function vlanTextLayout(width,height,n,roles,digits){
  n=Math.max(1,n);
  const gap=Math.min(8,Math.max(1,height/(n*12)));
  const available=Math.max(0,height-6-gap*(n-1)-roles*3);
  const font=Math.max(3,Math.min(36,(width-2)/(.62*Math.max(1,digits)),available/(n*1.15+roles*1.24)));
  return {gap,font};
}
