# ---- sw.js ----
ASSETS['/sw.js'] = "const CACHE='tps-portmap-20261021-port-status-6';
const ASSETS=['./','./index.html','./style.css','./overview.css','./physical.css','./app.js','./core.js','./data.json','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>event.waitUntil((async()=>{
  const cache=await caches.open(CACHE);
  for(const path of ASSETS){
    const response=await fetch(new Request(path,{cache:'reload'}));
    if(!response.ok||response.redirected)throw new Error('Authenticated resources unavailable');
    if(path.endsWith('.json')&&!response.headers.get('content-type')?.includes('json'))throw new Error('Data not available');
    await cache.put(path,response);
  }
  await self.skipWaiting();
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
  for(const name of await caches.keys())if(name.startsWith('tps-portmap-')&&name!==CACHE)await caches.delete(name);
  await self.clients.claim();
  for(const client of await self.clients.matchAll())client.postMessage({type:'OFFLINE_READY'});
})()));
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;
  const isNav=event.request.mode==='navigate';
  const known=ASSETS.some(p=>new URL(p,self.registration.scope).pathname===new URL(event.request.url).pathname);
  if(!isNav&&!known)return;
  event.respondWith((async()=>{
    try{
      const response=await fetch(event.request);
      // Login redirects/errors must never overwrite saved application data.
      return response;
    }catch{
      const saved=await caches.match(isNav?'./index.html':event.request,{ignoreSearch:true});
      return saved||new Response('오프라인 자료가 없습니다. 온라인으로 다시 접속하세요.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});
    }
  })());
});
".encode("utf-8")

CONTENT_TYPES = {'.html':'text/html; charset=utf-8', '.js':'text/javascript; charset=utf-8',
 '.css':'text/css; charset=utf-8', '.json':'application/json; charset=utf-8',
 '.webmanifest':'application/manifest+json; charset=utf-8', '.svg':'image/svg+xml', '.png':'image/png'}

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_asset()

    def do_HEAD(self):
        self.send_asset(head=True)

    def send_asset(self, head=False):
        path = unquote(urlsplit(self.path).path)
        if path == '/':
            path = '/index.html'
        payload = ASSETS.get(path)
        if payload is None:
            self.send_error(404, 'Not found')
            return
        suffix = '.' + path.rsplit('.', 1)[-1]
        self.send_response(200)
        self.send_header('Content-Type', CONTENT_TYPES.get(suffix, 'application/octet-stream'))
        self.send_header('Content-Length', str(len(payload)))
        self.send_header('Cache-Control', 'no-cache')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        if not head:
            self.wfile.write(payload)

    def log_message(self, fmt, *args):
        pass

class Server(ThreadingHTTPServer):
    daemon_threads = True


def main():
    parser = argparse.ArgumentParser(description='고양모터스 TPS 포트맵 단일 파일 웹앱')
    parser.add_argument('--port', type=int, default=8080, help='서버 포트 (기본 8080)')
    parser.add_argument('--lan', action='store_true', help='같은 네트워크의 휴대폰 접속 허용')
    parser.add_argument('--no-browser', action='store_true', help='브라우저 자동 열기 생략')
    args = parser.parse_args()
    if not 1 <= args.port <= 65535:
        parser.error('포트 번호는 1~65535 범위여야 합니다.')
    try:
        server = Server(('0.0.0.0' if args.lan else '127.0.0.1', args.port), Handler)
    except OSError as exc:
        print(f'서버 시작 실패: {exc}
다른 포트를 지정하세요: --port 8081')
        return 1
    url = f'http://localhost:{args.port}/'
    print(f'고양모터스 TPS 포트맵 실행 중
PC 접속: {url}
종료: Ctrl+C')
    if args.lan:
        print('휴대폰: PC와 같은 Wi-Fi에서 http://PC의IPv4주소:%d/ 접속' % args.port)
        print('PC IPv4 주소는 Windows ipconfig에서 확인할 수 있습니다.')
        print('휴대폰 접속 중에는 이 프로그램과 PC를 켜두세요. 필요 시 개인 네트워크 방화벽에서 Python을 허용하세요.')
        try:
            addresses = sorted({entry[4][0] for entry in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET)})
            for ip in addresses:
                if not ip.startswith('127.'):
                    print(f'접속 주소 후보: http://{ip}:{args.port}/')
        except OSError:
            pass
    if not args.no_browser:
        webbrowser.open(url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print('
포트맵을 종료합니다.')
    finally:
        server.server_close()
    return 0

if __name__ == '__main__':
    raise SystemExit(main())
